-- ROLLBACK PLAN: forward-only. Non-prod: DROP TABLE file_edit_versions CASCADE.
--   Prod: new forward migration; do not edit this file. Dropping the table only loses edit-version metadata —
--   the S3 objects it points at are not deleted by this migration and must be cleaned up separately if desired.
-- Group: spreadsheet-prep editing of already-uploaded CSV/TSV files (file-ingestion, internal/transform +
--   internal/editsave). A row is written only after the edited object has been written to S3 and checksummed
--   (same verify-before-commit discipline as file_objects/objects.Verify), so every row names a real, verified
--   object. Rows are insert-only once written (the applied ops never change after the fact); only deleted_at is
--   ever updated afterwards, hence no updated_at/trigger, matching file_objects (0004) itself.
--   `ops` holds the user-authored pipeline config (column names, rename targets, split/merge delimiters,
--   find/replace literals, regex patterns) that produced this version. Unlike the 0012 classifier convention
--   ("store label/field names, never matched values"), this table DOES contain literal find/replace text and
--   delimiters: it is explicit user configuration needed to audit or redo an edit, not a detector's findings
--   over file content, and it never contains a sample of the file's actual row data.
--   This feature does not enqueue a jobs row and is independent of the ClickHouse sink path (no FK to jobs).
-- RLS: new table, tenant-scoped like file_objects (0004).

CREATE TABLE file_edit_versions (
  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id          uuid NOT NULL REFERENCES tenants(id),
  file_object_id     uuid NOT NULL,
  version_number     int   NOT NULL CHECK (version_number >= 1),
  ops                jsonb NOT NULL CHECK (jsonb_typeof(ops) = 'array'),
  input_header_row   boolean NOT NULL DEFAULT true,
  output_header_row  boolean NOT NULL DEFAULT true,
  output_delimiter   text NOT NULL CHECK (length(output_delimiter) = 1),
  header             jsonb NOT NULL CHECK (jsonb_typeof(header) = 'array'),
  bucket             text NOT NULL,
  object_key         text NOT NULL,
  checksum_sha256    text NOT NULL,
  size_bytes         bigint NOT NULL CHECK (size_bytes >= 0),
  row_count          bigint NOT NULL CHECK (row_count >= 0),
  requested_by       text,
  created_at         timestamptz NOT NULL DEFAULT now(),
  deleted_at         timestamptz,
  FOREIGN KEY (tenant_id, file_object_id) REFERENCES file_objects (tenant_id, id),
  UNIQUE (tenant_id, id),
  UNIQUE (tenant_id, file_object_id, version_number)
);
CREATE INDEX file_edit_versions_file_ix ON file_edit_versions (tenant_id, file_object_id, version_number DESC);
CREATE INDEX file_edit_versions_ops_gin ON file_edit_versions USING gin (ops jsonb_path_ops);

SELECT astryon_enable_rls('file_edit_versions');
